<?php
$rootPath = '../'; require_once __DIR__ . '/../config/auth.php'; require_admin(); $bookings = $pdo->query('SELECT b.*, u.name AS user_name, e.name AS equipment_name FROM bookings b JOIN users u ON u.id = b.user_id JOIN equipment e ON e.id = b.equipment_id ORDER BY b.booking_date DESC, b.start_time DESC')->fetchAll(); $pageTitle = 'All bookings'; require __DIR__ . '/../includes/header.php';
?><section class="page-intro container"><p class="eyebrow">SCHEDULE</p><h1>All bookings.</h1><p>Review and cancel reservations across the gym.</p></section><section class="table-wrap container"><table><thead><tr><th>Member</th><th>Equipment</th><th>Date</th><th>Time</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($bookings as $booking): ?><tr><td><?= e($booking['user_name']) ?></td><td><?= e($booking['equipment_name']) ?></td><td><?= e($booking['booking_date']) ?></td><td><?= e(substr($booking['start_time'], 0, 5)) ?> - <?= e(substr($booking['end_time'], 0, 5)) ?></td><td><span class="status <?= $booking['status'] === 'confirmed' ? 'available' : 'cancelled' ?>"><?= e(ucfirst($booking['status'])) ?></span></td><td><?php if ($booking['status'] === 'confirmed'): ?><form method="post" action="cancel.php"><input type="hidden" name="id" value="<?= (int) $booking['id'] ?>"><button class="text-button danger" data-confirm="Cancel this booking?">Cancel</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></section><?php require __DIR__ . '/../includes/footer.php'; ?>
